using System;using System.Windows.Controls;
namespace KianaPet {
 public sealed partial class SettingsWindow {
  readonly TextBlock startupStatusText=new TextBlock{TextWrapping=System.Windows.TextWrapping.Wrap,Margin=new System.Windows.Thickness(0,12,0,12)};
  void BuildStartupPage(TabControl tabs){var page=Page(tabs,"启动与联动");TitleText(page,"随桌宠启动应用");Check(page,"打开桌宠时，同时启动 ChatGPT",pet.Settings.LaunchChatGPTOnStart,delegate(bool value){pet.Settings.LaunchChatGPTOnStart=value;pet.ApplySettings();});Check(page,"打开桌宠时，同时启动网易云音乐",pet.Settings.LaunchMusicOnStart,delegate(bool value){pet.Settings.LaunchMusicOnStart=value;pet.ApplySettings();});Note(page,"两项默认关闭，仅在下次启动桌宠时执行一次。已经运行的应用不会被重复启动或强制退出；打开设置、休眠唤醒和重复点击桌面图标都不会再次启动应用。普通方式运行的应用可能需要从托盘退出后重新连接。");page.Children.Add(startupStatusText);TitleText(page,"按需打开");page.Children.Add(Button("打开 ChatGPT",pet.LaunchChatGPT,false));page.Children.Add(Button("连接网易云音乐",pet.LaunchMusic,false));page.Children.Add(Button("检查并修复 ChatGPT 联动",pet.RepairChatGPT,true));Note(page,"检查只处理 ChatGPT：缺少启动会话时打开连接启动器，Mini 关闭时重新准备，通知缺失时切到备用状态。不会强制重启应用，不会结束语音或清空草稿；已连接时不反复启动其他软件。");}
  void BuildNotificationExperience(Panel page){TitleText(page,"提醒方式");Check(page,"静默提醒（只保留铃铛，不播放声音或弹出气泡）",pet.Settings.NoticeQuiet,delegate(bool v){pet.Settings.NoticeQuiet=v;pet.ApplySettings();});Check(page,"播放轻提示音",pet.Settings.NoticeSound,delegate(bool v){pet.Settings.NoticeSound=v;pet.ApplySettings();});Check(page,"普通任务完成静默，仅保留铃铛提示",pet.Settings.NoticeSilentSuccess,delegate(bool v){pet.Settings.NoticeSilentSuccess=v;pet.ApplySettings();});AddSlider(page,"完成提醒停留时间（秒）",2,30,pet.Settings.CompletionNoticeSeconds,1,delegate(int v){pet.Settings.CompletionNoticeSeconds=v;pet.ApplySettings();});AddSlider(page,"短暂断线保留通知（秒）",10,120,pet.Settings.NotificationGraceSeconds,5,delegate(int v){pet.Settings.NotificationGraceSeconds=v;pet.ApplySettings();});Note(page,"停留时间控制桌宠提醒气泡；未读角标保留到实际已读。提示音默认关闭，静默和免打扰优先。首次连接不会把已有未读任务全部重新提醒。断线期间角标变灰，列表标注最后同步时间并暂停跳转；连接恢复后立即按实际状态更新。");}
 }
}
